n = int(input())
if n > 11:
    print(0)
    exit()

arr = [list(map(int, input().split())) for _ in range(n)]

import math

eps = 1e-9

class Vector:
    def __init__(self, a, b):
        self.arr = [b[i] - a[i] for i in range(5)]
    def mag(self):
        return math.sqrt(sum(x * x for x in self.arr))
    def prod(self, v):
        return sum(self.arr[i] * v.arr[i] for i in range(5))

result = []

for i in range(n):
    good = True
    for j in range(n):
        if j == i:
            continue
        for k in range(j + 1, n):
            if k == i:
                continue
            v1 = Vector(arr[i], arr[j])
            v2 = Vector(arr[i], arr[k])
            angle = math.acos(v1.prod(v2) / (v1.mag() * v2.mag()))
            if angle < math.pi / 2 - eps:
                good = False
                break
        if not good:
            break
    if good:
        result.append(i + 1)

print(len(result))
for i in result:
    print(i)

